def build_agent(sandbox):
    # Create a wide hull for buoyancy and stability
    hull = sandbox.add_beam(x=5.0, y=1.5, width=2.0, height=1.0, density=100.0)
    sandbox.set_material_properties(hull, restitution=0.05)
    return [hull]

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    if front_x >= target_x + 0.1:
        # Stop all movement
        for b in sandbox.bodies:
            if b.active:
                sandbox.apply_force(b, -520.0, 0.0, step_count=step_count)
        return

    # Check if in deep channel (reduced buoyancy)
    in_danger_zone = (16.5 <= front_x <= 19.5)

    # Apply propulsion to hull every 3 steps
    if step_count % 3 == 0:
        sandbox.apply_force(agent_body, 520.0, 0.0, step_count=step_count)

    # Apply lift force in deep channel to counteract reduced buoyancy
    if in_danger_zone:
        sandbox.apply_force(agent_body, 0.0, 400.0, step_count=step_count)
